+const { useState, useRef } = React;
+
+const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+// E.164-ish: optional +, digits, spaces, dashes, parens; 7-15 digits total
+const PHONE_RE = /^\+?[\d\s().-]{7,}$/;
+
+function FormField({ id, label, type, required, autoComplete, value, onChange, onBlur, error, helperId, helperText, inputRef, inputMode }) {
+  const errorId = `${id}-error`;
+  const describedBy = [helperText ? helperId : null, error ? errorId : null].filter(Boolean).join(' ') || undefined;
+
+  return (
+    <div className="form-field">
+      <label htmlFor={id}>
+        {label}
+        {required && <span className="required-marker" aria-hidden="true">*</span>}
+        {!required && <span className="optional-text"> (optional)</span>}
+      </label>
+      <input
+        ref={inputRef}
+        id={id}
+        name={id}
+        type={type}
+        inputMode={inputMode}
+        required={required}
+        autoComplete={autoComplete}
+        value={value}
+        onChange={onChange}
+        onBlur={onBlur}
+        aria-invalid={error ? 'true' : 'false'}
+        aria-describedby={describedBy}
+      />
+      {helperText && (
+        <p className="helper-text" id={helperId}>{helperText}</p>
+      )}
+      {error && (
+        <p className="error-text" id={errorId}>Error: {error}</p>
+      )}
+    </div>
+  );
+}
+
+function ContactForm() {
+  const [values, setValues] = useState({ name: '', email: '', phone: '' });
+  const [errors, setErrors] = useState({});
+  const [status, setStatus] = useState('');
+
+  const refs = {
+    name: useRef(null),
+    email: useRef(null),
+    phone: useRef(null),
+  };
+
+  function validateField(field, value) {
+    const v = value.trim();
+    if (field === 'name') {
+      if (!v) return 'Enter your full name.';
+    }
+    if (field === 'email') {
+      if (!v) return 'Enter your email address.';
+      if (!EMAIL_RE.test(v)) return 'Enter a valid email address like name@example.com.';
+    }
+    if (field === 'phone') {
+      if (v && !PHONE_RE.test(v)) return 'Enter a valid phone number, for example +1 555 123 4567.';
+    }
+    return null;
+  }
+
+  function validateAll(vals) {
+    const next = {};
+    ['name', 'email', 'phone'].forEach(f => {
+      const err = validateField(f, vals[f]);
+      if (err) next[f] = err;
+    });
+    return next;
+  }
+
+  function handleChange(field) {
+    return (e) => {
+      const value = e.target.value;
+      setValues(prev => ({ ...prev, [field]: value }));
+      if (errors[field]) {
+        const err = validateField(field, value);
+        setErrors(prev => {
+          const copy = { ...prev };
+          if (err) copy[field] = err; else delete copy[field];
+          return copy;
+        });
+      }
+    };
+  }
+
+  function handleBlur(field) {
+    return (e) => {
+      const err = validateField(field, e.target.value);
+      setErrors(prev => {
+        const copy = { ...prev };
+        if (err) copy[field] = err; else delete copy[field];
+        return copy;
+      });
+    };
+  }
+
+  function handleSubmit(e) {
+    e.preventDefault();
+    setStatus('');
+    const next = validateAll(values);
+    setErrors(next);
+    const order = ['name', 'email', 'phone'];
+    const firstInvalid = order.find(f => next[f]);
+    if (firstInvalid) {
+      const node = refs[firstInvalid].current;
+      if (node) node.focus();
+      return;
+    }
+    setStatus(`Thanks, ${values.name.trim()}. Your message has been received and our support team will reply soon.`);
+    setValues({ name: '', email: '', phone: '' });
+  }
+
+  return (
+    <form className="contact-form" onSubmit={handleSubmit} noValidate aria-labelledby="form-heading">
+      <p className="form-legend">
+        Fields marked with <span className="required-marker" aria-hidden="true">*</span> are required.
+      </p>
+
+      <FormField
