+    setValues({ name: '', email: '', phone: '' });
+  }
+
+  return (
+    <form className="contact-form" onSubmit={handleSubmit} noValidate aria-labelledby="form-heading">
+      <p className="form-legend">
+        Fields marked with <span className="required-marker" aria-hidden="true">*</span> are required.
+      </p>
+
+      <FormField
+        id="name"
+        label="Full name"
+        type="text"
+        required
+        autoComplete="name"
+        value={values.name}
+        onChange={handleChange('name')}
+        onBlur={handleBlur('name')}
+        error={errors.name}
+        inputRef={refs.name}
+      />
+
+      <FormField
+        id="email"
+        label="Email address"
+        type="email"
+        required
+        autoComplete="email"
+        value={values.email}
+        onChange={handleChange('email')}
+        onBlur={handleBlur('email')}
+        error={errors.email}
+        inputRef={refs.email}
+      />
+
+      <FormField
+        id="phone"
+        label="Phone number"
+        type="tel"
+        inputMode="tel"
+        autoComplete="tel"
+        value={values.phone}
+        onChange={handleChange('phone')}
+        onBlur={handleBlur('phone')}
+        error={errors.phone}
+        helperId="phone-help"
+        helperText="Include country code if outside the US, for example +1 555 123 4567."
+        inputRef={refs.phone}
+      />
+
+      <div className="form-actions">
+        <button type="submit" className="btn-primary">Send message</button>
+      </div>
+
+      <div className="form-status" role="status" aria-live="polite">
+        {status}
+      </div>
+    </form>
+  );
+}
