  await page.goto(file, { waitUntil: 'networkidle0' });
  await page.waitForSelector('form.contact-form', { timeout: 10000 });

  const run = async (label) => {
    const r = await new AxePuppeteer(page).analyze();
    console.log(`\n=== ${label}: ${r.violations.length} violations ===`);
    for (const v of r.violations) {
      console.log(`- [${v.impact}] ${v.id}: ${v.help}`);
      v.nodes.slice(0,3).forEach(n => console.log('  •', n.target.join(' '), '|', n.failureSummary?.split('\n')[0]));
    }
  };

  await run('Initial');

  // Trigger errors
  await page.click('button[type=submit]');
  await new Promise(r => setTimeout(r, 300));
  await run('After invalid submit');

  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

